#!/usr/bin/env python3
"""Writes scan.comp: curve25519 in 8 32-bit limbs with no 64-bit integers.
Generated because every limb is a scalar local, which GPU compilers keep in
registers, where an array would cost them scratch memory."""
P = 2**255 - 19
D = (-121665 * pow(121666, P - 2, P)) % P
D2 = 2 * D % P
SQRT_M1 = pow(2, (P - 1) // 4, P)
L = range(8)


def const(name, value):
    limbs = ", ".join(f"{(value >> (32 * i)) & 0xffffffff}u" for i in L)
    return f"const Fe {name} = Fe({limbs});\n"


out = """#version 450
// Generated by gen_shader.py. 8aR for a fixed a and many R, in stages so that
// one dispatch stays short: INIT decompresses R and builds its table of 1R..8R,
// WINDOW takes STEPS signed base-16 digits of a, FINAL does 8x and hands back a
// projective point, for the CPU to compress with one inversion across the batch.
// CHECK runs one field operation, for the tests: the optimiser drops it otherwise.
//
// Nothing here varies with a's digits but the values held: every table entry is
// read for every digit, and the choice is made with masks.
layout(local_size_x_id = 0) in;
layout(constant_id = 1) const int STAGE = 0;
layout(constant_id = 2) const int STEPS = 1;
layout(push_constant) uniform Digits { int d[16]; uint count; } pc;
layout(std430, set = 0, binding = 0) readonly buffer Input { uint r[]; } input_keys;
layout(std430, set = 0, binding = 1) buffer State { uint s[]; } state;
layout(std430, set = 0, binding = 2) writeonly buffer Output { uint o[]; } output_keys;

struct Fe { uint """ + ", ".join(f"a{i}" for i in L) + """; };
"""
out += const("ZERO", 0) + const("ONE", 1) + const("D", D) + const("D2", D2) + const("SQRT_M1", SQRT_M1)

# Adds c*38 back in, where c is what came off the top.
def fold(c):
    s = f"    uint k; r.a0 = uaddCarry(r.a0, {c} * 38u, k);\n"
    for i in range(1, 8):
        s += f"    r.a{i} = uaddCarry(r.a{i}, k, k);\n"
    return s + "    r.a0 += k * 38u;\n"


out += "Fe fadd(Fe a, Fe b) {\n    Fe r; uint c = 0u, c1, c2, t;\n"
for i in L:
    out += f"    t = uaddCarry(a.a{i}, b.a{i}, c1); r.a{i} = uaddCarry(t, c, c2); c = c1 + c2;\n"
out += fold("c") + "    return r;\n}\n"

out += "Fe fsub(Fe a, Fe b) {\n    Fe r; uint c = 0u, c1, c2, t;\n"
for i in L:
    out += f"    t = usubBorrow(a.a{i}, b.a{i}, c1); r.a{i} = usubBorrow(t, c, c2); c = c1 + c2;\n"
out += "    uint k; r.a0 = usubBorrow(r.a0, c * 38u, k);\n"
for i in range(1, 8):
    out += f"    r.a{i} = usubBorrow(r.a{i}, k, k);\n"
out += "    r.a0 -= k * 38u;\n    return r;\n}\n"

# t0..t15 to a reduced Fe: low + 38 * high.
def reduce_wide():
    s = "    Fe r; uint rc = 0u, rh, rl, rc1, rc2, rx;\n"
    for i in L:
        s += f"    umulExtended(t{8+i}, 38u, rh, rl); rx = uaddCarry(t{i}, rl, rc1); r.a{i} = uaddCarry(rx, rc, rc2); rc = rh + rc1 + rc2;\n"
    return s + fold("rc") + "    return r;\n"


# Adds (hi, lo) to the three-word column accumulator.
def acc(hi, lo):
    return (f"r0 = uaddCarry(r0, {lo}, c0); r1 = uaddCarry(r1, c0, c1); r2 += c1; "
            f"r1 = uaddCarry(r1, {hi}, c1); r2 += c1;\n")


out += "Fe fmul(Fe a, Fe b) {\n    uint r0 = 0u, r1 = 0u, r2 = 0u, c0, c1, ph, pl;\n"
for k in range(15):
    for i in L:
        j = k - i
        if 0 <= j < 8:
            out += f"    umulExtended(a.a{i}, b.a{j}, ph, pl); {acc('ph', 'pl')}"
    out += f"    uint t{k} = r0; r0 = r1; r1 = r2; r2 = 0u;\n"
out += "    uint t15 = r0;\n" + reduce_wide() + "}\n"

out += "Fe fsq(Fe a) {\n    uint r0 = 0u, r1 = 0u, r2 = 0u, c0, c1, ph, pl;\n"
for k in range(15):
    pairs = [(i, k - i) for i in L if 0 <= k - i < 8 and i < k - i]
    if pairs:
        # The column's cross products, then doubled, then the column before's carry.
        out += "    {\n        uint s0 = r0, s1 = r1, s2 = r2; r0 = 0u; r1 = 0u; r2 = 0u;\n"
        for i, j in pairs:
            out += f"        umulExtended(a.a{i}, a.a{j}, ph, pl); {acc('ph', 'pl')}"
        out += "        r2 = (r2 << 1) | (r1 >> 31); r1 = (r1 << 1) | (r0 >> 31); r0 <<= 1;\n"
        out += "        " + acc("s1", "s0")
        out += "        r2 += s2;\n    }\n"
    if k % 2 == 0:
        out += f"    umulExtended(a.a{k//2}, a.a{k//2}, ph, pl); {acc('ph', 'pl')}"
    out += f"    uint t{k} = r0; r0 = r1; r1 = r2; r2 = 0u;\n"
out += "    uint t15 = r0;\n" + reduce_wide() + "}\n"

out += "Fe fneg(Fe a) { return fsub(ZERO, a); }\n"
out += """Fe fsqn(Fe a, int n) { for (int i = 0; i < n; i++) a = fsq(a); return a; }
// a^(2^250-1), and a^11 beside it.
Fe fpow250(Fe a, out Fe eleven) {
    Fe t0 = fsq(a);
    Fe t2 = fmul(a, fsqn(t0, 2));
    eleven = fmul(t0, t2);
    Fe t5 = fmul(t2, fsq(eleven));
    Fe t7 = fmul(fsqn(t5, 5), t5);
    Fe t9 = fmul(fsqn(t7, 10), t7);
    Fe t11 = fmul(fsqn(t9, 20), t9);
    Fe t13 = fmul(fsqn(t11, 10), t7);
    Fe t15 = fmul(fsqn(t13, 50), t13);
    Fe t17 = fmul(fsqn(t15, 100), t15);
    return fmul(fsqn(t17, 50), t13);
}
"""
# To the one value under p.
out += "Fe freeze(Fe x) {\n    uint k = x.a7 >> 31; x.a7 &= 0x7fffffffu;\n    Fe y; uint c;\n"
out += "    x.a0 = uaddCarry(x.a0, k * 19u, c);\n"
for i in range(1, 8):
    out += f"    x.a{i} = uaddCarry(x.a{i}, c, c);\n"
out += "    y.a0 = uaddCarry(x.a0, 19u, c);\n"
for i in range(1, 8):
    out += f"    y.a{i} = uaddCarry(x.a{i}, c, c);\n"
out += "    uint over = 0u - (y.a7 >> 31); y.a7 &= 0x7fffffffu;\n    Fe r;\n"
for i in L:
    out += f"    r.a{i} = (y.a{i} & over) | (x.a{i} & ~over);\n"
out += "    return r;\n}\n"
out += "bool feq(Fe a, Fe b) {\n    a = freeze(a); b = freeze(b);\n    return " + " && ".join(f"a.a{i} == b.a{i}" for i in L) + ";\n}\n"
out += "Fe sload(uint at) { return Fe(" + ", ".join(f"state.s[at + {i}u]" for i in L) + "); }\n"
out += "void sstore(uint at, Fe v) {\n" + "".join(f"    state.s[at + {i}u] = v.a{i};\n" for i in L) + "}\n"

out += """
struct Ext { Fe x, y, z, t; };
struct Comp { Fe x, y, z, t; };
struct Proj { Fe x, y, z; };
struct Niels { Fe yp, ym, z, t2d; };

Ext comp_ext(Comp c) { return Ext(fmul(c.x, c.t), fmul(c.y, c.z), fmul(c.z, c.t), fmul(c.x, c.y)); }
Proj comp_proj(Comp c) { return Proj(fmul(c.x, c.t), fmul(c.y, c.z), fmul(c.z, c.t)); }
Comp pdouble(Proj p) {
    Fe xx = fsq(p.x), yy = fsq(p.y), zz = fsq(p.z);
    Fe zz2 = fadd(zz, zz);
    Fe xy = fsq(fadd(p.x, p.y));
    Fe sum = fadd(yy, xx), diff = fsub(yy, xx);
    return Comp(fsub(xy, sum), sum, diff, fsub(zz2, diff));
}
Comp eadd(Ext e, Niels n) {
    Fe pp = fmul(fadd(e.y, e.x), n.yp);
    Fe mm = fmul(fsub(e.y, e.x), n.ym);
    Fe tt = fmul(e.t, n.t2d);
    Fe zz = fmul(e.z, n.z);
    Fe zz2 = fadd(zz, zz);
    return Comp(fsub(pp, mm), fadd(pp, mm), fadd(zz2, tt), fsub(zz2, tt));
}
Niels niels(Ext e) { return Niels(fadd(e.y, e.x), fsub(e.y, e.x), e.z, fmul(e.t, D2)); }

// One key's state: Q (4 Fe), then a table of 1R..8R (8 Niels), then a flag.
const uint STRIDE = 300u;
const uint TABLE = 32u;
const uint FLAG = 288u;

""" + "Fe fselect(Fe a, Fe b, uint m) {\n    return Fe(" + ", ".join(f"(a.a{i} & ~m) | (b.a{i} & m)" for i in L) + """);
}

// A key's table, held in the shader's registers while it works through a dispatch.
Fe typ[8], tym[8], tz[8], tt2d[8];

void load_table(uint base) {
    for (uint i = 0u; i < 8u; i++) {
        uint at = base + TABLE + i * 32u;
        typ[i] = sload(at);
        tym[i] = sload(at + 8u);
        tz[i] = sload(at + 16u);
        tt2d[i] = sload(at + 24u);
    }
}

// The entry for a digit, reading them all: all ones in m when i is the digit's size.
Niels table_entry(int digit) {
    uint negative = uint(digit) >> 31;
    uint size = (uint(digit) ^ (0u - negative)) + negative;
    Fe yp = ONE, ym = ONE, z = ONE, t2d = ZERO;
    for (uint i = 0u; i < 8u; i++) {
        uint differs = size ^ (i + 1u);
        uint m = ((differs | (0u - differs)) >> 31) - 1u;
        yp = fselect(yp, typ[i], m);
        ym = fselect(ym, tym[i], m);
        z = fselect(z, tz[i], m);
        t2d = fselect(t2d, tt2d[i], m);
    }
    uint n = 0u - negative;
    return Niels(fselect(yp, ym, n), fselect(ym, yp, n), z, fselect(t2d, fneg(t2d), n));
}

void init_stage(uint key, uint base) {
    uint in_at = key * 8u;
""" + "    Fe y = Fe(" + ", ".join(f"input_keys.r[in_at + {i}u]" for i in L) + """);
    // The CPU sends only canonical keys, with no negative zero.
    uint sign = y.a7 >> 31;
    y.a7 &= 0x7fffffffu;
    Fe yy = fsq(y);
    Fe u = fsub(yy, ONE);
    Fe v = fadd(fmul(yy, D), ONE);
    Fe v3 = fmul(fsq(v), v);
    Fe v7 = fmul(fsq(v3), v);
    Fe eleven;
    Fe root = fmul(fsqn(fpow250(fmul(u, v7), eleven), 2), fmul(u, v7));
    Fe x = fmul(fmul(u, v3), root);
    Fe check = fmul(v, fsq(x));
    uint bad = 0u;
    if (feq(check, fneg(u))) x = fmul(x, SQRT_M1);
    else if (!feq(check, u)) bad = 1u;
    if ((freeze(x).a0 & 1u) != sign) x = fneg(x);
    state.s[base + FLAG] = bad;
    Ext p = Ext(x, y, ONE, fmul(x, y));
    Niels n = niels(p);
    Niels first = n;
    Ext q = p;
    for (uint i = 0u; i < 8u; i++) {
        uint at = base + TABLE + i * 32u;
        sstore(at, n.yp); sstore(at + 8u, n.ym); sstore(at + 16u, n.z); sstore(at + 24u, n.t2d);
        if (i < 7u) { q = comp_ext(eadd(q, first)); n = niels(q); }
    }
    // Q starts as the top digit's multiple.
    load_table(base);
    Ext e = comp_ext(eadd(Ext(ZERO, ONE, ONE, ZERO), table_entry(pc.d[0])));
    sstore(base, e.x); sstore(base + 8u, e.y); sstore(base + 16u, e.z); sstore(base + 24u, e.t);
}

void window_stage(uint base) {
    Ext q = Ext(sload(base), sload(base + 8u), sload(base + 16u), sload(base + 24u));
    load_table(base);
    for (int w = 0; w < STEPS; w++) {
        Proj s = Proj(q.x, q.y, q.z);
        for (int i = 0; i < 3; i++) s = comp_proj(pdouble(s));
        q = comp_ext(pdouble(s));
        q = comp_ext(eadd(q, table_entry(pc.d[w])));
    }
    sstore(base, q.x); sstore(base + 8u, q.y); sstore(base + 16u, q.z); sstore(base + 24u, q.t);
}

void final_stage(uint key, uint base) {
    Proj s = Proj(sload(base), sload(base + 8u), sload(base + 16u));
    for (int i = 0; i < 3; i++) s = comp_proj(pdouble(s));
    uint at = key * 25u;
""" + "".join(f"    output_keys.o[at + {i}u] = s.x.a{i};\n    output_keys.o[at + {8+i}u] = s.y.a{i};\n    output_keys.o[at + {16+i}u] = s.z.a{i};\n" for i in L) + """    output_keys.o[at + 24u] = state.s[base + FLAG];
}

void check_stage(uint key) {
    uint in_at = key * 16u;
""" + "    Fe a = Fe(" + ", ".join(f"input_keys.r[in_at + {i}u]" for i in L) + ");\n    Fe b = Fe(" + ", ".join(f"input_keys.r[in_at + {8+i}u]" for i in L) + """);
    Fe r;
    if (pc.d[0] == 0) r = fadd(a, b);
    else if (pc.d[0] == 1) r = fsub(a, b);
    else if (pc.d[0] == 2) r = fmul(a, b);
    else if (pc.d[0] == 3) r = fsq(a);
    else if (pc.d[0] == 4) r = fneg(a);
    else r = a;
    r = freeze(r);
    uint at = key * 25u;
""" + "".join(f"    output_keys.o[at + {i}u] = r.a{i};\n" for i in L) + """}

void main() {
    uint key = gl_GlobalInvocationID.x;
    if (key >= pc.count) return;
    uint base = key * STRIDE;
    if (STAGE == 0) init_stage(key, base);
    else if (STAGE == 1) window_stage(base);
    else if (STAGE == 2) final_stage(key, base);
    else check_stage(key);
}
"""
open(__file__.replace("gen_shader.py", "scan.comp"), "w").write(out)
